<?php
namespace App\Finance;
use App\Harvest\HarvestBook;
use App\Field\FieldProblem;
use Brick\Math\BigDecimal;
class AdministrationBook
{
 public function __construct(private \CodeIgniter\Database\BaseConnection $db){}
 public function filters(array $q):array{$from=HarvestBook::date($q['date_from']??gmdate('Y-m-01'));$to=HarvestBook::date($q['date_to']??gmdate('Y-m-d'));if($from>$to)throw new FieldProblem(422,'Período inválido.');foreach(['harvest_id','client_id','worker_id']as$k)if(isset($q[$k])&&$q[$k]!==''&&(!ctype_digit((string)$q[$k])||(int)$q[$k]<1))throw new FieldProblem(422,'Filtro inválido.');if(!in_array($q['kind']??'',['','receipt','payment','expense'],true))throw new FieldProblem(422,'Tipo de movimento inválido.');return [$from,$to];}
 public function portfolio(array $q=[]):array{
  HarvestBook::requireAdmin();[$from,$to]=$this->filters($q);$book=new HarvestBook($this->db);$out=[];$movements=[];$settlements=[];$pending=[];$expenses=[];
  $totals=array_fill_keys(['received_cents','paid_cents','paid_expense_cents','cash_cents','receivable_cents','payable_cents','pending_receipt_cents','pending_payment_cents','pending_expense_cents','expense_cents','margin_cents','received_period_cents','paid_period_cents','expense_period_cents'],0);$validation=0;
  foreach($this->db->table('agri_harvests')->where('starts_on <=',$to)->orderBy('id','DESC')->get()->getResultArray()as$raw){if(!empty($q['harvest_id'])&&(int)$q['harvest_id']!==(int)$raw['id'])continue;if(!empty($q['client_id'])&&(int)$q['client_id']!==(int)$raw['client_id'])continue;$h=$book->detail((int)$raw['id']);$s=array_fill_keys(['received_cents','paid_cents','paid_expense_cents','cash_cents','receivable_cents','payable_cents','pending_receipt_cents','pending_payment_cents','pending_expense_cents','expense_cents','margin_cents','received_period_cents','paid_period_cents','expense_period_cents'],0);$s['produced']='0';$s['delivered']='0';$s['weighed']='0';$validLogs=[];$waiting=0;
   foreach($h['activities']as$l){if($l['work_date']>$to)continue;if($l['status']==='closed'&&substr($l['closed_at']??$l['work_date'],0,10)<=$to)$validLogs[(int)$l['id']]=true;if($l['status']==='submitted')$waiting++;}
   foreach($h['workers']as$a)if(isset($validLogs[(int)$a['work_log_id']])){$s['payable_cents']+=(int)$a['amount_cents'];$s['produced']=(string)BigDecimal::of($s['produced'])->plus($a['quantity']);}
   foreach($h['deliveries']as$d)if($d['delivered_on']<=$to){$s['receivable_cents']+=ProductionBook::cents((string)BigDecimal::of($d['billing_quantity'])->multipliedBy($d['billing_rate']??$h['billing_rate']));$s['delivered']=(string)BigDecimal::of($s['delivered'])->plus($d['payment_quantity']);$s['weighed']=(string)BigDecimal::of($s['weighed'])->plus($d['billing_quantity']);}
   foreach($h['expenses']as$e)if($e['recognized_on']<=$to){$s['expense_cents']+=(int)$e['amount_cents'];$e['paid_cents']=0;foreach($h['movements']as$m)if((int)($m['expense_id']??0)===(int)$e['id']&&$m['paid_on']<=$to)$e['paid_cents']+=(int)$m['amount_cents'];$expenses[]=$e+['contract_name'=>$h['name']];}
   foreach($h['movements']as$m){if($m['paid_on']>$to)continue;$key=['receipt'=>'received_cents','payment'=>'paid_cents','expense'=>'paid_expense_cents'][$m['kind']];$s[$key]+=(int)$m['amount_cents'];if($m['kind']==='expense'&&empty($m['expense_id']))$s['expense_cents']+=(int)$m['amount_cents'];if($m['paid_on']>=$from){$period=['receipt'=>'received_period_cents','payment'=>'paid_period_cents','expense'=>'expense_period_cents'][$m['kind']];$s[$period]+=(int)$m['amount_cents'];if((empty($q['kind'])||$q['kind']===$m['kind'])&&(empty($q['worker_id'])||(int)$m['worker_id']===(int)$q['worker_id']))$movements[]=$m+['contract_name'=>$h['name'],'source'=>'contract'];}}
   $s['cash_cents']=$s['received_cents']-$s['paid_cents']-$s['paid_expense_cents'];$s['margin_cents']=$s['receivable_cents']-$s['payable_cents']-$s['expense_cents'];$s['pending_receipt_cents']=$s['receivable_cents']-$s['received_cents'];$s['pending_payment_cents']=$s['payable_cents']-$s['paid_cents'];$s['pending_expense_cents']=$s['expense_cents']-$s['paid_expense_cents'];$s['partial']=$waiting>0||$h['status']==='active'||BigDecimal::of($s['produced'])->compareTo($s['delivered'])!==0;$s['waiting']=$waiting;$validation+=$waiting;
   foreach($totals as$k=>$v)$totals[$k]+=$s[$k];$out[]=['id'=>(int)$h['id'],'name'=>$h['name'],'client_id'=>(int)$h['client_id'],'client_name'=>$h['client_name'],'site_name'=>$h['site_name'],'starts_on'=>$h['starts_on'],'ends_on'=>$h['ends_on'],'status'=>$h['status'],'version'=>(int)$h['version'],'payment_unit_name'=>$h['payment_unit_name'],'billing_unit_name'=>$h['billing_unit_name'],'summary'=>$s];
  }
  $settlements=$this->db->table('agri_contract_settlements s')->select('s.*,w.name AS worker_name,h.name AS contract_name')->join('agri_workers w','w.id=s.worker_id')->join('agri_harvests h','h.id=s.harvest_id')->where('s.created_at <=',$to.' 23:59:59')->get()->getResultArray();$settlements=array_values(array_filter($settlements,fn($s)=>(empty($q['harvest_id'])||(int)$s['harvest_id']===(int)$q['harvest_id'])&&(empty($q['worker_id'])||(int)$s['worker_id']===(int)$q['worker_id'])&&(empty($q['client_id'])||in_array((int)$s['harvest_id'],array_column($out,'id'),true))));
  foreach($settlements as&$s){unset($s['request_hash']);$paid=0;foreach($this->db->table('agri_harvest_movements')->where('settlement_id',$s['id'])->where('paid_on <=',$to)->get()->getResultArray()as$m)$paid+=(int)$m['amount_cents'];foreach($this->db->table('agri_contract_payment_credits c')->select('c.amount_cents')->join('agri_harvest_movements m','m.id=c.movement_id')->where('c.settlement_id',$s['id'])->where('m.paid_on <=',$to)->get()->getResultArray()as$m)$paid+=(int)$m['amount_cents'];$s['paid_cents']=$paid;}unset($s);
  $unclosed=$this->db->table('agri_harvest_allocations a')->select('l.harvest_id,h.name AS contract_name,a.worker_id,w.name AS worker_name,MIN(l.work_date) AS date_from,MAX(l.work_date) AS date_to,SUM(a.amount_cents) AS amount_cents,COUNT(*) AS activities')->join('agri_work_logs l','l.id=a.work_log_id')->join('agri_harvests h','h.id=l.harvest_id')->join('agri_workers w','w.id=a.worker_id')->join('agri_contract_settlement_items i','i.work_log_id=a.work_log_id AND i.worker_id=a.worker_id','left')->join('agri_contract_settlements closed_settlement','closed_settlement.id=i.settlement_id','left')->groupStart()->where('i.settlement_id',null)->orWhere('closed_settlement.created_at >',$to.' 23:59:59')->groupEnd()->where('l.closed_at <=',$to.' 23:59:59')->where('l.status','closed')->where('l.work_date >=',$from)->where('l.work_date <=',$to)->groupBy(['l.harvest_id','h.name','a.worker_id','w.name'])->get()->getResultArray();foreach($unclosed as$p)if((empty($q['harvest_id'])||(int)$p['harvest_id']===(int)$q['harvest_id'])&&(empty($q['worker_id'])||(int)$p['worker_id']===(int)$q['worker_id'])&&(empty($q['client_id'])||in_array((int)$p['harvest_id'],array_column($out,'id'),true)))$pending[]=$p;
  if(empty($q['harvest_id'])&&empty($q['client_id'])){foreach($this->db->table('agri_payment_entries p')->select('p.*,s.worker_id,w.name AS worker_name')->join('agri_settlements s','s.id=p.settlement_id')->join('agri_workers w','w.id=s.worker_id')->where('p.paid_on <=',$to)->get()->getResultArray()as$m){$totals['paid_cents']+=(int)$m['amount_cents'];$totals['cash_cents']-=(int)$m['amount_cents'];if($m['paid_on']>=$from){$totals['paid_period_cents']+=(int)$m['amount_cents'];if((empty($q['kind'])||$q['kind']==='payment')&&(empty($q['worker_id'])||(int)$m['worker_id']===(int)$q['worker_id']))$movements[]=$m+['kind'=>'payment','harvest_id'=>null,'contract_name'=>'Anterior aos contratos','source'=>'legacy'];}}
   $legacy=(int)($this->db->table('agri_earnings')->selectSum('amount_cents','total')->where('created_at <=',$to.' 23:59:59')->get()->getRowArray()['total']??0);$legacyPaid=(int)($this->db->table('agri_payment_entries')->selectSum('amount_cents','total')->where('paid_on <=',$to)->get()->getRowArray()['total']??0);$totals['payable_cents']+=$legacy;$totals['pending_payment_cents']+=$legacy-$legacyPaid;
  }
  usort($movements,fn($a,$b)=>strcmp($b['paid_on'],$a['paid_on'])?:((int)$b['id']<=>(int)$a['id']));$flow=['receipt'=>0,'payment'=>0,'expense'=>0];foreach($movements as$m)$flow[$m['kind']]+=(int)$m['amount_cents'];
  return ['contracts'=>$out,'totals'=>$totals,'movements'=>$movements,'expenses'=>$expenses,'settlements'=>$settlements,'pending'=>$pending,'flow'=>$flow,'waiting'=>$validation,'settlements_with_balance'=>count(array_filter($settlements,fn($s)=>(int)$s['paid_cents']<(int)$s['total_cents'])),'period'=>['from'=>$from,'to'=>$to]];
 }
}
